/**
 * PRODUCT-A-MVP-SPIKE-1B.2 — versioned, additive ground-truth corrections.
 *
 * Corrections live beside the fixture spec, never inside it, so the spec hash,
 * the generated bytes and every earlier result stay unchanged. A correction can
 * only ADD an accepted value for a field whose truth is `present`; anything
 * else is rejected. Callers score under the original truth and, separately,
 * under the corrected truth.
 */

import { readFileSync } from 'node:fs'
import path from 'node:path'
import { EXTRACTED_FIELD_NAMES, type ExtractedFieldName } from '../receipt-examination/schema'
import { FIXTURE_HISTORY_DIR, specSha256, type ResolvedFixture } from './fixtures'

/**
 * v1 corrections apply only to the frozen v1 spec (their base hash pins it).
 * receipt-fixtures-v2 already includes the adjudicated value, so applying
 * these to v2 is refused.
 */
export const DEFAULT_TRUTH_CORRECTIONS_PATH = path.join(FIXTURE_HISTORY_DIR, 'receipt-truth-corrections-v1.json')

export interface TruthCorrection {
  fixture_id: string
  field: ExtractedFieldName
  add_value_accept: string[]
  adjudicated: string
  rationale: string
}

export interface TruthCorrections {
  corrections_version: string
  base_spec_version: string
  base_spec_sha256: string
  policy: string
  corrections: TruthCorrection[]
}

export function loadTruthCorrections(file = DEFAULT_TRUTH_CORRECTIONS_PATH): TruthCorrections {
  return JSON.parse(readFileSync(file, 'utf8')) as TruthCorrections
}

/** Returns new fixtures with corrections applied; inputs are not mutated. Throws on any non-additive correction. */
export function applyTruthCorrections(fixtures: ResolvedFixture[], c: TruthCorrections, specHash = specSha256()): ResolvedFixture[] {
  if (c.base_spec_sha256 !== specHash) throw new Error(`${c.corrections_version} was written for a different fixture spec`)
  const byId = new Map(fixtures.map((f) => [f.id, f]))
  const out = new Map(fixtures.map((f) => [f.id, { ...f, value_accept: { ...f.value_accept } }]))
  for (const k of c.corrections) {
    if (!EXTRACTED_FIELD_NAMES.includes(k.field)) throw new Error(`correction for unknown field ${k.field}`)
    if (!k.rationale?.trim()) throw new Error(`correction ${k.fixture_id}.${k.field} has no rationale`)
    if (!Array.isArray(k.add_value_accept) || k.add_value_accept.length === 0 || k.add_value_accept.some((v) => typeof v !== 'string' || !v.trim())) {
      throw new Error(`correction ${k.fixture_id}.${k.field} must add at least one non-empty value`)
    }
    const original = byId.get(k.fixture_id)
    if (!original) continue // fixture not in the selected subset
    if (original.truth[k.field].status !== 'present') throw new Error(`correction ${k.fixture_id}.${k.field}: truth is not 'present'`)
    const f = out.get(k.fixture_id)!
    f.value_accept[k.field] = [...(f.value_accept[k.field] ?? []), ...k.add_value_accept]
  }
  return fixtures.map((f) => out.get(f.id)!)
}
